import { z } from 'zod';

// `code` is auto-generated by the service (PROMO-0001, PROMO-0002, ...)
// unless the client supplies one explicitly — same convention as every
// other master (see promotion.service.js's nextPromotionCode()).
export const createPromotionSchema = z
  .object({
    code: z.string().trim().min(1).optional(),
    promotionName: z.string().trim().min(1, 'Promotion name is required'),
    promotionType: z.enum(['Percentage Off', 'Amount Off', 'Buy X Get Y', 'Bundle Offer'], {
      errorMap: () => ({ message: 'Select a promotion type' }),
    }),
    description: z.string().trim().max(500).optional().or(z.literal('')).nullable(),
    appliesTo: z.enum(['all', 'specific', 'category'], {
      errorMap: () => ({ message: 'Select who this applies to' }),
    }),
    discountType: z.enum(['Percentage', 'Flat Amount', 'Free Item', 'Special Price'], {
      errorMap: () => ({ message: 'Select a discount type' }),
    }),
    // Coerced to a number here (never trusted as-is from the client) so
    // "10abc" or a negative value can never reach the database — the
    // frontend's own zod schema blocks these at the form too, but the
    // backend is the actual source of truth.
    discountValue: z.coerce.number().nonnegative('Discount value cannot be negative').default(0),
    discountUnit: z.enum(['%', '₹']).default('%'),
    maximumUsage: z.enum(['no-limit', 'once-per-customer', 'once-per-bill']).default('no-limit'),
    minimumBillAmount: z.coerce.number().nonnegative('Minimum bill amount cannot be negative').default(0),
    startDate: z.coerce.date({ errorMap: () => ({ message: 'Start date is required' }) }),
    endDate: z.coerce.date().optional().nullable(),
    noExpiry: z.coerce.boolean().default(false),
    usageLimitEnabled: z.coerce.boolean().default(false),
    usageLimitCount: z.coerce.number().int('Usage limit must be a whole number').nonnegative().default(0),
    onePerCustomer: z.coerce.boolean().default(false),
    combinable: z.coerce.boolean().default(true),
    showInInvoice: z.coerce.boolean().default(true),
    selectedItems: z.array(z.string().trim().min(1)).default([]),
    selectedCategories: z.array(z.string().trim().min(1)).default([]),
  })
  .superRefine((values, ctx) => {
    if (!values.noExpiry && !values.endDate) {
      ctx.addIssue({ code: z.ZodIssueCode.custom, path: ['endDate'], message: 'End date is required' });
    }
    if (values.endDate && values.endDate < values.startDate) {
      ctx.addIssue({ code: z.ZodIssueCode.custom, path: ['endDate'], message: 'End date cannot be before start date' });
    }
    if (values.appliesTo === 'specific' && values.selectedItems.length === 0) {
      ctx.addIssue({ code: z.ZodIssueCode.custom, path: ['selectedItems'], message: 'Select at least one item' });
    }
    if (values.appliesTo === 'category' && values.selectedCategories.length === 0) {
      ctx.addIssue({ code: z.ZodIssueCode.custom, path: ['selectedCategories'], message: 'Select at least one category' });
    }
    if (values.discountType === 'Percentage' && values.discountUnit === '%' && values.discountValue > 100) {
      ctx.addIssue({ code: z.ZodIssueCode.custom, path: ['discountValue'], message: 'Percentage discount cannot exceed 100%' });
    }
    if (values.usageLimitEnabled && values.usageLimitCount <= 0) {
      ctx.addIssue({ code: z.ZodIssueCode.custom, path: ['usageLimitCount'], message: 'Enter a usage limit greater than 0' });
    }
  });

// Edit mode always resubmits the whole form (see CreatePromotionPage), so the
// update schema keeps the same full validation instead of `.partial()` —
// a partial update here would let a half-filled payload silently erase
// required fields like promotionType or startDate.
export const updatePromotionSchema = createPromotionSchema;
